INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('one-way-heroics-plus', 147990, '2015-08-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5anc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard9f.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Way Heroics Plus', 'A world controlled by darkness. In game, the darkness constantly advances from the left side of the screen, swallowing up the map. If you are swallowed by the darkness, it''s game over. You cannot turn back. The screen will continue to scroll right even while shopping or fighting enemies. You must keep advancing and save the world.In One Way Heroics, if the player moves or attacks enemies will do the same. In essence, it is a rogue-like game. To clear the game, you must defeat the Demon Lord, who will appear after a set time.One round is around 30 minutes play time, and some parts of your legend carry over into the next round. See if you can overcome the challenges of this one way adventure.' FROM games WHERE igdb_id = 147990 ON CONFLICT (game_id, language_code) DO NOTHING;
