INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Lands: Dark Overlord', 'Susan had just stepped away to answer the phone, but when she returned she saw something pulling her son Jimmy through a shimmering portal. It closed before she could pull him back. To save him, she must find a way to this other world. Before Susan lies a world that no one else has ever seen before... a world where magic is real and anything is possible. Find out who took Jimmy and what they want in Lost Lands: Dark Overlord!' FROM games WHERE igdb_id = 35078 ON CONFLICT (game_id, language_code) DO NOTHING;
