INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fly in the House', 'You''re back home after a few years of traveling. When you walked into your apartment, memories came flooding back to you. Many questions require answers. You start to wonder what''s wrong with your life, but suddenly notice a fly in the house. Everything else is forgotten and replaced with one burning desire - kill the fly!' FROM games WHERE igdb_id = 10326 ON CONFLICT (game_id, language_code) DO NOTHING;
