INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-1 Drive', 'F-1 Drive is a 3D racing mini game. The goal is simple, to run the best laps you can. The game has a unique feature that transfers the computer control to study the behavior of bots and then come up with the best tactics for overtaking. Features: 7 car rivals, 5 racetracks, system damage, original music.' FROM games WHERE igdb_id = 347815 ON CONFLICT (game_id, language_code) DO NOTHING;
