INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bunker: The Underground Game', 'This is Bunker: The Underground Game. You probably never heard of it but since you now have, you are one of the cool kids. Game takes place deep down in a forgotten Soviet bunker. You spend rest of your absurd adventure puzzling, mini gaming, pointing, clicking, hipstering, err humor-ing oh and escaping what is no doubt the weirdest bunker you have ever been unwillingly dragged to.' FROM games WHERE igdb_id = 35661 ON CONFLICT (game_id, language_code) DO NOTHING;
