INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Charnel House Trilogy', 'Witness The Charnel House Trilogy, the chronicle of one fateful night aboard a train bound for Augur Peak. Three thrilling, horrifying adventure games in one, from the depths of the Sepulchre, starring Madeleine Roux, Peter Willington, Jonathan Grier, Jim Sterling, and Ben Chandler as Grub. With art by Ivan Ulyanov and Ben Chandler, and music by Jack de Quidt, nervous_testpilot and Bryan Henderson.' FROM games WHERE igdb_id = 19385 ON CONFLICT (game_id, language_code) DO NOTHING;
