INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slashy Hero', 'In a world where evil monsters have stolen all of the candy, there is just one hero who can save Halloween. Suit up in your favorite costume and slash your way through hordes of ghouls, jack-o-lanterns, and other meanies in this award winning action game. You must survive the horrors of the haunted mansion and recover the lost candy to return Halloween to its former glory!' FROM games WHERE igdb_id = 31357 ON CONFLICT (game_id, language_code) DO NOTHING;
