INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sirius Online', 'Sirius Online is a unique, easy to play Space Action Shooter with Multiplayer components and ongoing progression. Join the Ranks of the Terran Reclaim Forces or the Sirius Colonial Council today and fight for your Faction! Explore forgotten battlefields, find Treasures, create an empire with your friends and rule the universe!' FROM games WHERE igdb_id = 35288 ON CONFLICT (game_id, language_code) DO NOTHING;
