INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hungry Shark World', 'Hungry Shark World is a mobile game where players take on the role of a hungry shark navigating through various underwater environments, from the ocean depths to bustling coastal cities. The main goal is to survive and thrive by consuming anything edible in sight, including fish, humans, and other marine creatures. As players progress, they can upgrade their shark with various abilities and unlock new species with unique traits.' FROM games WHERE igdb_id = 58597 ON CONFLICT (game_id, language_code) DO NOTHING;
