INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fuego!', 'Fuego is an online Mexican standoff game between two opposing players and their teams of gun toting animal-banditos. The game starts in the standoff where players position and orient their banditos one at a time, in double blind turns. During the standoff players are trying to unravel the impending shootout while identifying strategic linchpins and outsmarting their opponent.' FROM games WHERE igdb_id = 13206 ON CONFLICT (game_id, language_code) DO NOTHING;
