INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caribbean Odyssey', 'Step into the epic adventure of the legendary pirate Captain Henry Morgan. Inspired by true events from 16th century, Caribbean Odyssey is a beautiful tale of loyalty, love, betrayal and revenge. Explore a lavish and colorful world of secrets in 2.5D. The journey of Captain Morgan takes you through Caribbean islands, caves, dungeons, jungles and populated cities. Unfold the mysterious truth as the most wanted pirate of the Caribbean flees from the city of Port Royal to escape the wrath of evil Governor Thomas Modyford. Does he really have the map to the mythical City of Gold?' FROM games WHERE igdb_id = 34132 ON CONFLICT (game_id, language_code) DO NOTHING;
