INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Towelket 0: Maiden Bomb Invaders', 'Maiden Bomb Invaders is a free JRPG made by Kanao (Kanashimi Hocchikisu). This game serves as a retelling of Towelket 5, with a primary focus on the Bomb Maidens from the earlier entries. The narrative takes a slight twist to introduce new plots and characters. As a spin-off of the main series Towelket One More Time, it references elements and features characters from the previous entries. It is suggested to play at least Towelket 1 and Towelket 5 to fully understand it.' FROM games WHERE igdb_id = 282444 ON CONFLICT (game_id, language_code) DO NOTHING;
