INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dissidia Final Fantasy Arcade', 'The RPG/fighting game phenomenon from Square Enix returns with an all-new 3-on-3 battle style and evolved visuals in this original arcade fighter. The initial game roster featured 14 heroes representing the main entries from the series, with villains and additional heroes added in subsequent updates. The game was later adapted for PlayStation 4 as Dissidia Final Fantasy NT.' FROM games WHERE igdb_id = 24405 ON CONFLICT (game_id, language_code) DO NOTHING;
