INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choice of the Petal Throne', 'Choice of the Petal Throne is a 124,000-word interactive fantasy novel, where your choices control the story. It''s entirely text-based - without graphics or sound effects - and fueled by the vast, unstoppable power of your imagination. As a captain in one of their armies, will you play as male or female, gay straight or bi? A brave and forthright soldier, a hedonistic intriguer with a heart of gold, or scheming double agent?' FROM games WHERE igdb_id = 35582 ON CONFLICT (game_id, language_code) DO NOTHING;
