INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninjahtic Mind Tricks', 'Ninjahtic Mind Tricks is an 8-bit hack-and-slash platformer with stealth, adventure, and puzzle elements. Like it''s predecessor, Ninjahtic, levels have an open-ended nature and are presented in a linear fashion. Though, several features have been added to the predecessor''s formula to create a more varied experience.' FROM games WHERE igdb_id = 34818 ON CONFLICT (game_id, language_code) DO NOTHING;
