INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yasumeru', 'Yasumeru is a Yume Nikki fangame. This game stars Yasashi, a boy living in a small house on a hill. The goal is to explore and collect effects. After waking up, you can see the time of day changes every time you sleep. It cycles from morning, to afternoon, to night, to dusk, then back to morning. There is also a small chance of rain when you wake up.' FROM games WHERE igdb_id = 202344 ON CONFLICT (game_id, language_code) DO NOTHING;
