INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuuki Yuna wa Yuusha de Aru: Jukai no Kioku', 'Yuki Yuna wa Yuusha de Aru: Jukai no Kioku is a Japanese action game and is based on the media franchise Yuuki Yuna wa Yuusha de Aru. The story follows the five female club members of the Sanshu Middle School Hero Club, who are tasked of protecting the world from mysterious monsters known as Vertex. The game is divided into two sections: Action Part and Event Part. Action Part plays as a 3D action game where the player must defeat mysterious monsters called "the Vertex" playing as one of the five hero club members. Event Part plays like a traditional visual novel and tells the story of the game.' FROM games WHERE igdb_id = 11784 ON CONFLICT (game_id, language_code) DO NOTHING;
