INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burstfire', 'Burstfire is a tactical, competitive, first-person shooter that is a fusion of old-school tactical combat with modern design sensibilities that allow for a slower combat pace while maintaining a high level of excitement and fun! Play as the attacking "SWAT" team to breach through enemy "MERC" defenses using tools such as the "Breaching Charge" or the "Hacking Device" to carefully, and precisely capture your objective, the enemy "INTEL COM". Play as the defending "MERC" team, setting up defensible positions around the "INTEL COM", your primary defense objective, using tools such as the Wooden Barricades and Wall Reinforcements.' FROM games WHERE igdb_id = 35766 ON CONFLICT (game_id, language_code) DO NOTHING;
