INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MagNets', 'MagNets: an intense arcade-style robot-recycling collect-em-up! Players must fight to restore order in Polarity City, one arena at a time. Do this by capturing malfunctioning Bloxbots in your Electromagnetic Nets (or ''MagNets''), and recycling them into tools to complete the level and power-ups to survive their attacks!' FROM games WHERE igdb_id = 10535 ON CONFLICT (game_id, language_code) DO NOTHING;
