INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cults and Daggers', 'Cults and Daggers is a strategy game set in the time between the death of the Buddha and the birth of Christ. You create your own religion and fight a secret war for the soul of the world. The game includes, spies, assassinations, double dealing, occult forces, martyrs, prophets and blasphemers.' FROM games WHERE igdb_id = 36160 ON CONFLICT (game_id, language_code) DO NOTHING;
