INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ev3-drag-racing', 88251, '2015-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobdbv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hyjeqbx0cluakx6swjp7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EV3 - Drag Racing', 'EV3 is built by real life drag racers. The fun of drag racing is driving, not just pushing buttons. In EV3 you actually drive the car using realistic variable gas pedal, steering, braking, realistic suspension and engine/torque response... It''s all there. When you drive a car in EV3 you actually experience all the thrills and spills of real racing. In EV3 you actually feel like you''re in control, because you are!' FROM games WHERE igdb_id = 88251 ON CONFLICT (game_id, language_code) DO NOTHING;
