INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dropsy: Warm Damp Hug', 'After a deadly circus fire shatters his world and tarnishes his name, Dropsy the Clown finds himself on a journey of self-discovery through a story that harnesses powerful themes of love and kindness. The Dropsy Warm Damp Hug includes the official Dropsy digital soundtrack by Chris Schlarb, the Eternal Hug music EP by Jay Tholen, and Dropsy''s Book of Secrets - a collection of tips, sketches, concepts and ramblings from designer Jay Tholen.' FROM games WHERE igdb_id = 51748 ON CONFLICT (game_id, language_code) DO NOTHING;
