INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battles-of-the-ancient-world-iii', 197344, '2015-06-04', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battles of the Ancient World III', 'The ''Battles of the Ancient World'' game system is a tactical simulation of some of the greatest and most important battles from 1457 B.C. to 378 A.D.. Each, of the 5 scenarios available, features one of these great battles and players may play as either side. Each unit in the game represents an actual unit that participated in the battle, each with an actual strength between 250 and 1,200 men. The map represents the actual terrain over which each battle was fought. The game in the series has been designed to ensure maximum playability and historical accuracy, in that order. There are 60 different units across all the missions, ranging from elite Roman Legionaries, to Egyptian Chariots. Each unit has its own unique ability that you need to take advantage of in order to win each battle.' FROM games WHERE igdb_id = 197344 ON CONFLICT (game_id, language_code) DO NOTHING;
