INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic GML', 'A fan‑made 2D Sonic the Hedgehog game created in GameMaker: Studio using GameMaker Language (GML). Released in 2015 by independent developer ZykovEddy, it recreates the look and feel of the classic Mega Drive/Genesis Sonic titles while introducing original level layouts, custom sprites, and unique gimmicks. Distributed freely online for Windows PC, it is not affiliated with or endorsed by SEGA.' FROM games WHERE igdb_id = 332208 ON CONFLICT (game_id, language_code) DO NOTHING;
