INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deliverance', 'Deliverance is a first-person survival horror game in which you are put into the captivity of a deranged man dawning a serial killing streak with no plans to stop. Play as "Victim #3" and try to find your way out of your captor''s imprisonment as you explore a maze-like abandoned asylum.' FROM games WHERE igdb_id = 14639 ON CONFLICT (game_id, language_code) DO NOTHING;
