INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unheard Screams: King Leopold II''s Rule Over the Congo', 'Unheard Screams is a text based roleplaying game. You play as Miala, a Congolese liberator attempting to overthrow the regime of King Leopold II of Belgium (1885-1908). As the player your job is to fight the foreign oppressors and regain control of territories in the Congo while managing your rebellion''s resources.' FROM games WHERE igdb_id = 35383 ON CONFLICT (game_id, language_code) DO NOTHING;
