INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('number-idarb', 9888, '2015-01-30', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wlw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7g69.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '#IDARB', 'Prepare to battle everything from Moustache Cops to Breakfast, in this game inspired by fast action, 8-bit sports and arcade classics! Built with the input of thousands of crazed internet gamers, #IDARB is a chaotic 8-player eSport jumping future arena ball game. Create characters, teams, team logos, tournaments, even your theme music, in this highly customizable experience complete with disruptive “hashbombs” which dynamically change the game itself via Twitch and Twitter! IDARB supports up to a whopping 8 simultaneous local players, and up to 4 vs. 4, head-to-head online matches. Additional features include a mind-blowing single-player story mode, wild half time competitions, and unlockable recipes. Begun as a crowd-sourced project, the game’s title is an acronym for “It Draws a Red Box” (IDARB). Thanks to thousands of suggestions via social media, the game evolved from one red box into the wacky amalgam it is today, complete with hundreds of strange “hashbombs”, secret commands which, when sent to the game via Twitch or Twitter, will disrupt and dynamically change the game in realtime! If there’s something you want that isn’t in #IDARB, it’s probably because you didn’t suggest it, but with so many customization options, you can probably still make it yourself!' FROM games WHERE igdb_id = 9888 ON CONFLICT (game_id, language_code) DO NOTHING;
