INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gratuitous Space Battles 2', 'Have you ever wanted to be admiral of a huge, sprawling space battle-fleet of your own design? Ever wanted to design a fleet of battle-cruisers so powerful they can rip all who oppose them into space-dust? Ever wanted to build a battleship with purple rotating radars and 64 engines? Well we have good news for you...INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 35873 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
