INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('judgement-silversword-resurrection', 36405, '2015-09-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zwo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aregl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Judgement Silversword: Resurrection', 'Judgement Silversword is the winner of the "WonderWitch" 2001 game development contest, and was originally released in 2004. Designed for the WonderSwan Color, Judgement Silversword has the unique distinction of being one of the few shooting games designed for a handheld console, and it''s also one of the best! Destroying enemies as quickly as possible is essential to scoring in Judgement Silversword, giving the game a ruthless tempo. One of indie developer M-KAI''s first games, it can be seen as the inspiration and predecessor to the gameplay ideas in Eschatos.
