INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('resident-evil-revelations-2', 7725, '2015-02-24', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co92d9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ykn6jkxpk7bwffmqmux6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil: Revelations 2', 'Resident Evil: Revelations 2 is the retail version of the episodic survival horror series that was originally released as four downloadable episodes. This physical version combines the entire story along with some extras, but not all the available DLC. The PC version did not receive a retail release, but the same content was bundled on Steam. The game comprises four episodes, each of which feature two separate stories. This sequel bears a stronger tone to the concept of survival horror than titles such as Resident Evil 5 and Resident Evil 6. Elements of ammunition management as well as stealth or sneaking come into play in the gameplay.' FROM games WHERE igdb_id = 7725 ON CONFLICT (game_id, language_code) DO NOTHING;
