INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catlateral Damage', 'Catlateral Damage is a first-person destructive cat simulator where you play as a cat on a rampage, knocking as much stuff onto the ground as possible. See the world through the eyes of a cat! Like other first-person games, you can walk and look around, jump, and crouch. Unlike other first-person games, your primary weapons are your two cat paws, which you can use to swipe at and knock objects onto the floor.' FROM games WHERE igdb_id = 17966 ON CONFLICT (game_id, language_code) DO NOTHING;
