INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caromble!', 'This is not just another brick breaker game. This is Caromble!, a fresh new take on the brick break game! Free the corrupted world and fight evil with physics-based destruction, puzzles, explosions, skill-levels, power-ups, mayhem, more explosions, further puzzles, speedruns, superscore medals, unlockable challenges and some surprises you would''t expect in a brick breaker game. Brick break your way to glory and discover a world of nostalgic wonder. Let’s get ready to Caromble!' FROM games WHERE igdb_id = 24655 ON CONFLICT (game_id, language_code) DO NOTHING;
