INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Listen', 'The puppetman is a creature that wanders the earth, unseen by almost everybody who is not close to death, but always ignored. He has almost given up on finding somebody to listen to his stories, when he meets a young girl who lives in a german hospice. As they open up for a quite unusual friendship, the little girl learns more about the puppetman''s past and the reason he remains unseen. But can she save him? Or does he save her?' FROM games WHERE igdb_id = 151582 ON CONFLICT (game_id, language_code) DO NOTHING;
