INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Voz Vol. 3', 'La Voz Vol. 3 is a karaoke game based on the Spanish television singing competition of the same name. Sing through 30 songs in Spanish and English, with modes that recreate the show''s various stages including blind auditions and battles. Play solo in career modes, compete against friends in multiplayer modes like duels and teams, or perform in the exclusive "The Show" mode that faithfully recreates the television program''s format. The game includes official music videos and supports optional microphone controllers for an authentic performance experience.' FROM games WHERE igdb_id = 268437 ON CONFLICT (game_id, language_code) DO NOTHING;
