INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmares from the Deep: Cursed Heart', 'Nightmares from the Deep: The Cursed Heart is a classic adventure game that tells a gripping tale of undying love. Assume the role of museum curator Sarah Black and take control of your destiny to stop the undead Captain Remington and save your daughter''s life. Jam-packed with chilling locations - from rotting shipwrecks to dank and mordant caves. Use your wits to find clues, solve puzzles, and uncoil the ancient mysteries of Skull Island before it''s too late!' FROM games WHERE igdb_id = 140247 ON CONFLICT (game_id, language_code) DO NOTHING;
