INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('infinite-stratos-2-love-and-purge', 11833, '2015-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mvh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nzkusk2j0hlihnaktfbp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinite Stratos 2: Love and Purge', 'Infinite Stratos 2: Love and Purge is a Japanese visual novel based on the Infinite Stratos light novel franchise. The game’s story is set several days after the "World Purge" chapter. It is an adventure game where the player’s relationship with the heroines change depending on your choices. During adventure parts, players will become Ichika Orimura and enjoy the academy life together with the heroines. By choosing the options that appear mid-conversation, Ichika’s "Braveheart Points", which signify his manhood, will fluctuate. Depending on its final value, the game’s ending will change. In communication mode, it’s possible to give the game’s heroines a massage in order to deepen your bonds. If successful, your Braveheart Points will go up. But if it fails, they will fall. Massage techniques include applying pressure to parts of the body with your finger, tapping the body part, lightly rubbing it, or simply asking where she would like to be massaged.' FROM games WHERE igdb_id = 11833 ON CONFLICT (game_id, language_code) DO NOTHING;
