INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alone in the Dark: Illumination', 'A darkness has fallen over the town of Lorwich. Monstrous hordes emerge from beyond the realm of nightmares to sow chaos on the land. As one of four heroes, you must battle the minions of the old ones with the force of arms, and the power of illumination.
