INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('regions', 134210, '2015-06-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2845.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3igp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Regions', 'Regions is an abstract, minimal puzzle game about drawing paths and understanding geometry. The 6 x 6 playing field is divided into different regions and your task is to draw a path that covers only one square of each. Later levels introduce regions that have different mechanics to keep things interesting across 160 levels. Regions also features a dynamic soundtrack that responds to how you play. 
