INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legions of Steel', 'Based on the original tactical board game "Legions of Steel" designed by Clark Browning, Marco Pecota and Derrick Villeneuve, where players fight battles in a dark and dangerous environment. French Developer Studio Nyx have managed to re-create the deep and challenging set of rules, while adding slick 3D models, a clever and accessible UI and a load of new features.' FROM games WHERE igdb_id = 17614 ON CONFLICT (game_id, language_code) DO NOTHING;
