INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Picture Cross', 'Picture Cross is a nonogram puzzle game. The game offers over 9,000 puzzles across 74 themed packs, featuring Classic and Color Picture Cross puzzles with grid sizes and difficulty levels ranging from Easy to Expert. Players solve logic puzzles by using number clues to fill in grid squares, revealing hidden pixel art images. The app includes leaderboards, achievements, and a tutorial for new players, with a free-to-play model that includes optional in-app purchases.' FROM games WHERE igdb_id = 89485 ON CONFLICT (game_id, language_code) DO NOTHING;
