INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lastronaut', 'Lastronaut is a pixel-packed, adrenaline-fueled dash for your life as you run, jump, dodge and blast your way through the machine army, equipped with an arsenal of human and robotic weapons to cause mayhem with. At dawn, as the rest of humanity lifts off in the distance, it’s your mission to reach the last rocket ship leaving Earth. Your life depends on it.' FROM games WHERE igdb_id = 344933 ON CONFLICT (game_id, language_code) DO NOTHING;
