INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('persona-4-dancing-all-night', 11056, '2015-06-25', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hmn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hvqz3ni279vx3zt76sad.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 4: Dancing All Night', 'Persona 4: Dancing All Night is a story-driven music game of the cult hit RPG Persona 4, developed by ATLUS. Replacing the RPG elements are dance battles that challenge players'' dexterity and accuracy, as they tap out re-mixes of fan-favorite themes and brand new music tracks. The storyline continues from after the events of Persona 4, when the teenage mega-idol, Rise Kujikawa, returns to the city to re-take her show biz career. During that time, a strange video appears on the internet and the unfortunate people who watched it have gone missing! Members of Kanamin Kitchen, Rise''s junior idol group, have disappeared and it''s up to the Investigation team to mount a rescue mission - only they discover the same monstrous Shadows from the Midnight Channel. To make matters even worse, their Persona abilities are rendered ineffective, and the Shadows in P4D can only be defeated by dance, so bust out powerful dance moves to save the day!' FROM games WHERE igdb_id = 11056 ON CONFLICT (game_id, language_code) DO NOTHING;
