INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starfighter: Eclipse', 'You are Helios, the newest fighter aboard the starship Kepler. Join Cain, Abel and the crew from Hamlet Machine''s webcomic, Starfighter, on board a brand new, interactive adventure. Your mission: join an Alliance surveillance team with Selene, your newly-assigned navigator, to investigate a derelict alien spacecraft. But when you return from the away mission, something is amiss, and it''s up to you to figure out why.' FROM games WHERE igdb_id = 142958 ON CONFLICT (game_id, language_code) DO NOTHING;
