INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Tractor', 'This totally serious, 100% accurate to life corn harvesting simulation experience will get your adrenaline pumping and nerves excited. You''ll never be able to farm for corn in the same light again! How much corn will YOU harvest before your eventual death by tractor? Don''t let your family, or the tractors, stop you from becoming the ultimate capitalist in DEATH TRACTOR!' FROM games WHERE igdb_id = 35115 ON CONFLICT (game_id, language_code) DO NOTHING;
