INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 4: Dancing All Night: Hanate Wotagei! Rise no Dance Battle', 'Persona 4: Dancing All Night: Hanate Wotagei! Rise no Dance Battle is a Flash game where Teddie battles Rise in a silly but colorful dance-off by timing your mouse clicking to the beat of the music before time runs out. Win or lose, Teddie asks the player to purchase the then-upcoming PlayStation Vita release of Persona 4: Dancing All Night and then tweet about it on Twitter.' FROM games WHERE igdb_id = 349557 ON CONFLICT (game_id, language_code) DO NOTHING;
