INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Devil Survivor 2 - Record Breaker', 'Your days are numbered. This is a chilling reminder that the apocalypse is upon us. Exclusive to the Nintendo 3DS handheld system, Shin Megami Tensei: Devil Survivor 2 Record Breaker offers more than 100 hours of gameplay and plot -- nearly double the content of the original Devil Survivor 2. It also includes fully voiced English story dialogue, giving new depth to the cast of Devil Survivor 2''s original story. Record Breaker requires no knowledge of the story from the original Devil Survivor, so newcomers to the series won''t lack any crucial plot information.' FROM games WHERE igdb_id = 23441 ON CONFLICT (game_id, language_code) DO NOTHING;
