INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Trigger: Borderless Mission', 'World Trigger: Borderless Mission is a 3D Action game made exclusively for the PS Vita based on the World Trigger manga series. There are 37 missions in the Story Mode, which are split into 9 Arcs which in order are: Special Training, Yuma, Jin, Tamakoma First, Arashiyama, Kazama, Tachikawa, Miwa, and Top Brass.' FROM games WHERE igdb_id = 12892 ON CONFLICT (game_id, language_code) DO NOTHING;
