INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted: Drake''s Fortune Remastered', 'Jump into the perilous journey that kick-started the legendary escapades of Nathan Drake. Hunt for the lost treasure of El Dorado, with the help of courageous journalist Elena Fisher and Drake’s mentor and friend Victor “Sully” Sullivan. Enjoy peerless storytelling from the team at Naughty Dog, as you race to discover the fabled city of gold before your ruthless enemies. Experience the classic PlayStation3 adventure that redefined the genre, now on PlayStation4.' FROM games WHERE igdb_id = 41878 ON CONFLICT (game_id, language_code) DO NOTHING;
