INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fasaria World Online', 'Fasaria World Online is a strategy, building RPG style mmo that can be played through any web browser even on your tablet or phone. Fasaria World Online is STEAM community exclusive which means ALL of our active members are from the steam community. Our membership requires a one time fee to join so no need to worry about having to pay to win. This model was also designed to support an active and cohesive community exclusive to it''s members.' FROM games WHERE igdb_id = 34530 ON CONFLICT (game_id, language_code) DO NOTHING;
