INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return to PopoloCrois: A Story of Seasons Fairytale', 'The fairy tale world of PoPoLoCrois meets the farm living of Story of Seasons in this cross-over RPG. It features classically-styled turn-based combat and towns full of lively and interesting NPCs who contribute to a heartwarming narrative that veterans or newcomers to either franchise can enjoy. Ample farming and life simulation elements such as crop-raising, bug-catching, rock quarrying, item synthesis and more round out the experience.' FROM games WHERE igdb_id = 11005 ON CONFLICT (game_id, language_code) DO NOTHING;
