INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faron''s Fate', 'Faron''s Fate is an action- roguelike about a lone adventurer venturing into a dungeon full of dangerous monsters and rare artifacts. Enter a procedurally generated dungeon, fight for your life, and collect weapons, loot, and armor along the way. By combining components of The Binding of Isaac and The Legend of Zelda with classic RPG elements, Faron''s Fate creates a unique action- packed experience where no two playthroughs are alike.' FROM games WHERE igdb_id = 34311 ON CONFLICT (game_id, language_code) DO NOTHING;
