INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Decisive Campaigns: Case Blue', 'Decisive Campaigns: Case Blue simulates the German drive to Stalingrad and into the Caucasus of the summer of 1942, as well as its May preludes (2nd Kharkov offensive, Operation Trappenjagd) and also the Soviet winter counter-offensive (Operation Uranus) that ended with the encirclement of 6th Army in Stalingrad.' FROM games WHERE igdb_id = 35666 ON CONFLICT (game_id, language_code) DO NOTHING;
