INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at Pinkie''s', 'Five Nights at Pinkie''s is a horror game where you are the night watcher at Pinkie''s Cupcakes Corner. Your job is to watch ponies animatronics (kind of robots) during the night from 12am to 6am. But the ponies are moving and they don''t have good intentions. Your weapons? Security cameras & doors with limited power. Will you survive 5 nights?' FROM games WHERE igdb_id = 228654 ON CONFLICT (game_id, language_code) DO NOTHING;
