INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at F***boy''s: Final Mix', 'Five Nights at F***boy’s is a FNaF fangame created by Sable Lynn and Joshua Shaw in RPG Maker VX Ace featuring unfair difficulty, text-to-speech voice acting, and beautiful, beautiful animatronic...things. The Final Mix edition add''s two extra playable side stories, each with their own plots and characters.' FROM games WHERE igdb_id = 170035 ON CONFLICT (game_id, language_code) DO NOTHING;
