INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenshu General', 'Tenshu General, is a simple, elegant, Real Time Strategy (RTS) game for those who favor short play sessions over long sessions. Quick casual game play combined with the challenge of continuously adapting enemies allow for a surprisingly challenging exercise in strategy. It is a cross breed between a board game and a classic RTS. If you like Risk or 8 Minute Empire, Tenshu General is your game.' FROM games WHERE igdb_id = 35473 ON CONFLICT (game_id, language_code) DO NOTHING;
