INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperdevotion Noire: Goddess Black Heart', 'Hyperdevotion Noire: Goddess Black Heart is a tactical role-playing game developed by Sting and Compile Heart The game is a spin-off title of the Hyperdimension Neptunia game series featuring Noire as the main character. The game features chibi versions of the original Hyperdimension Neptunia characters which battle against enemies on a tactical grid map. The gameplay is turn-based, and map elevation has an effect on characters'' abilities and mobility; certain units are more capable of climbing to higher terrain than others, and units take damage from falling. The field maps feature various gimmicks, including rail cars, flaming pits, logs, artillery batteries, laser beams and moving platforms.' FROM games WHERE igdb_id = 9871 ON CONFLICT (game_id, language_code) DO NOTHING;
