INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'rFactor 2', 'rFactor 2 is a realistic, easily extendable racing simulation that offers the latest in vehicle and race customization, great graphics, outstanding multiplayer and the height of racing realism. It features mixed class road racing with ultra realistic dynamics, an immersive sound environment and stunning graphics. You can race against both AI and other drivers in multi-player mode.' FROM games WHERE igdb_id = 9494 ON CONFLICT (game_id, language_code) DO NOTHING;
