INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JoJo''s Bizarre Adventure: Eyes of Heaven', 'JoJo’s Bizarre Adventure: Eyes of Heaven is an upcoming Japanese fighting game based on the long-running JoJo''s Bizarre Adventure manga franchise. Eyes of Heaven is designed to be a 3D action brawler with tag-team elements set in large arenas based on locations in the manga. Players may pick a single character to control in a large environment, as well as a second character that may be controlled by either a CPU or second human player to fight the enemy team for a 2v2 battle. Like in All-Star Battle characters are categorized by fighting styles, which currently includes Hamon, Ogre Street Techniques, Vampiric, German Science, Mode, Stand and Mounted.' FROM games WHERE igdb_id = 11565 ON CONFLICT (game_id, language_code) DO NOTHING;
