INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CortexGear:AngryDroids', 'CortexGear:AngryDroids is a clasic 3d Sci-Fi shooting sidescroller where quick tactics and skills need to be in harmony the beat the game. A run-and-gun shooter with both mouse and keyboard controls at the same time. An adventure game with a emotional story and epic game-play. Potentially therapeutic and emotionally educational, it''s a game for PC, Mac and Linux.' FROM games WHERE igdb_id = 35082 ON CONFLICT (game_id, language_code) DO NOTHING;
