INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assault Android Cactus', '"Assault Android Cactus is a manic twin stick arena shooter for the PC with screens full of enemies, buckets of bullets and high scoring combo chains! Take on the role of Cactus, an enthusiastic police android, who responds to a stranded space freighter only to discover it under siege by its malfunctioning robot workers. Cut off from the outside and in over her head, Cactus and the androids she recruits along the way battle through the crippled Genki Star to reach the brain of the ship and put things right before it''s too late."' FROM games WHERE igdb_id = 8644 ON CONFLICT (game_id, language_code) DO NOTHING;
