INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stock Car Extreme', 'Developed with support from real teams and drivers, Stock Car Extreme is one of the most highly regarded racing simulators for the PC. In addition to the current season of Stock Car V8 - a brazilian series featuring world class drivers such as Rubens Barrichello and Ricardo Zonta - Stock Car Extreme includes several extra series and tracks covering a wide variety of racing disciplines. It also enjoys a continuous flow of free updates to further stablish itself as one of the most realistic, complete and immersive titles in the racing simulation genre.' FROM games WHERE igdb_id = 16966 ON CONFLICT (game_id, language_code) DO NOTHING;
