INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Army Trilogy', 'Zombie Army Trilogy is a third-person tactical shooter stealth video game developed and published by Rebellion Developments. It is a spin-off to the Sniper Elite series, released on March 6, 2015 for Microsoft Windows, PlayStation 4 and Xbox One. The premise of the game is that, in an alternative version of the final days of World War II, with the German army close to defeat, Adolf Hitler deploys a last resort plan to raise the fallen as zombies through occult rituals and turn them against Allied forces, thus causing Germany to become overrun with the undead.' FROM games WHERE igdb_id = 20871 ON CONFLICT (game_id, language_code) DO NOTHING;
