INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danganronpa Another Episode: Ultra Despair Girls', 'Danganronpa Another Episode: Ultra Despair Girls is a horror action adventure spin-off game in the Danganronpa series of visual novel games, taking place between the events of Danganronpa: Trigger Happy Havoc and Danganronpa 2: Goodbye Despair. Unlike the visual novel gameplay of the previous games, Ultra Despair Girls is a third-person adventure game with horror elements, in which players control Komaru Naegi as she tries to survive in a city overrun by Monokuma robots.' FROM games WHERE igdb_id = 9708 ON CONFLICT (game_id, language_code) DO NOTHING;
