INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Doom Beneath', 'The Doom Beneath is a game-based graphic novel telling the story of a lone geologist who stumbles over a terrible secret deep underground. The gamebook offers a new twist on the choose-your-own-adventure style of storytelling, adding turn-based combat and role-playing game elements. With pulpy narration, dark humor, and hand-illustrated graphics, The Doom Beneath collides interactive fiction with adventure-horror, then adds a smooth layer of action on top.' FROM games WHERE igdb_id = 175429 ON CONFLICT (game_id, language_code) DO NOTHING;
