INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('evolve-hunters-quest', 21626, '2015-01-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hgthhuvxxo5kzzzr5krt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xuoruccbkmldybfaw1zr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evolve Hunters Quest', 'Evolve: Hunters Quest is a match 3 puzzle combat game based on the “Best of Show” E3 award winner, Evolve. Use match 3 tokens of the same color to unleash devastating attacks on your enemies, and fill up energy bars to activate hunters’ special abilities. Earn Mastery Points to rank up your character in both the mobile and console games. Explore the planet of Shear in search of new wildlife and monsters. Discover and complete your collection of exotic wildlife in the Bestiary, and earn unique art for the Evolve console game. Enhance your Evolve skills by watching your multiplayer match replays from a strategic top-down view, and devouring intel in the Game Changer. Evolve: Hunters Quest lets you continue your Evolve experience from anywhere!' FROM games WHERE igdb_id = 21626 ON CONFLICT (game_id, language_code) DO NOTHING;
