INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chariot-bundle', 82458, '2015-09-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mvzlk28zxgqui9kdub2z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kjstuzowjkalv9shxnr2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chariot Bundle', 'The Chariot Bundle includes Chariot and the Royal Gadget Pack DLC. Embark on a journey to take His Majesty on the ride of His afterlife. Guide a chariot containing the King''s remains through underground caves using physics-based mechanics such as pushing, pulling, riding and swinging. Alone or with a friend, lead the brave Princess and her faithful Fiancé into the royal catacombs to find the perfect resting place for the King! And that''s not all! The Shopkeeper joins the action, bringing along 5 new gadgets! Play as the Shopkeeper in solo or co-op and try out new technology delivered straight from the royal engineers'' workshop! Walk on ice, light up the darkness, swim in lava, freeze the world, teleport the Chariot through time and space, and much more! Also includes new achievements and blueprints hidden throughout existing levels. Help His Downloadable Majesty to rest in peace already!' FROM games WHERE igdb_id = 82458 ON CONFLICT (game_id, language_code) DO NOTHING;
