INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ronin', 'Ronin (stylized as RONIN) is a 2015 turn-based action platformer video game developed by Polish indie developer Tomasz Wacławek, designer at polish indie studio Flying Wild Hog, and published by Devolver Digital. It was released for Microsoft Windows on May 27, 2015 into Early Access and left it on June 30, 2015.' FROM games WHERE igdb_id = 11183 ON CONFLICT (game_id, language_code) DO NOTHING;
