INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted 2: Among Thieves Remastered', 'Reacquaint yourself with fortune hunter Nathan Drake through a tale of life-threatening danger, exotic locations and heroic rescue missions. Delve into the secrets of Marco Polo''s doomed voyage and the legendary Himalayan valley of Shambhala. You’ll cross paths with some old faces plus brand new adversaries, including a deadly fugitive war criminal. Tackle challenging puzzles, battle deadly foes and adventure across varied terrain ranging from snowy landscapes and jungles, to war-torn cityscapes and ancient temples. Experience the classic PlayStation3 adventure, now on PlayStation4.' FROM games WHERE igdb_id = 41877 ON CONFLICT (game_id, language_code) DO NOTHING;
