INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunset', 'It''s 1972 and a military coup has rocked Anchuria. You, Angela Burnes, are trapped in the metropolitan capital of San Bavón. Your paradise has turned into a warzone. You take up a job as a housekeeper. Every week, an hour before sunset, you clean the swanky bachelor pad of the wealthy Gabriel Ortega.' FROM games WHERE igdb_id = 14703 ON CONFLICT (game_id, language_code) DO NOTHING;
