INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights At Dungeon', 'This game is similar to Dungeon Nightmares but with the weapon. You must find five artifacts and survive for five nights. Only this time you have two weapons. One is melee and other is ranged. Can You Survive Five Night''s At Dungeon ? Search for clues, and fight your fears. Fight for your life!' FROM games WHERE igdb_id = 240161 ON CONFLICT (game_id, language_code) DO NOTHING;
