INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('choices-that-matter-and-the-sun-went-out', 147698, '2015-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3n3c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ara6j.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choices That Matter: And the Sun Went Out', 'And The Sun Went Out What if the sun inexplicably vanished only to return hours later? Investigate with your AI companion, Moti. Uncover conspiracies. Discover ancient religions. Travel the globe. Find out who is murdering scientists and what this has to do with the random disappearances of the sun. This is your journey, and only your choices can expose the truth. Approximately 600,000 words and 2,400 choices in total! See how many other players visited the same place as you, each time you conclude a story arc. CHOICES THAT MATTER is a collection of epic text adventure games similar to the classic Choose Your Path Adventure books. Our interactive stories are some of the most complex in the this category. No one player can discover the entire story in a single play through!' FROM games WHERE igdb_id = 147698 ON CONFLICT (game_id, language_code) DO NOTHING;
