INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovers in a Dangerous Spacetime', 'Lovers in a Dangerous Spacetime is a frantic 1- or 4-player couch co-op action space shooter set in a massive neon battleship. Only through teamwork can you triumph over the evil forces of Anti-Love, rescue kidnapped space-bunnies, and avoid a vacuumy demise. Deep space is a dangerous place, but you don’t have to face it alone!' FROM games WHERE igdb_id = 12520 ON CONFLICT (game_id, language_code) DO NOTHING;
