INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Superstatic', 'Superstatic is a top-down shooter where you''re given the ability to possess and control your enemies. Using "copies", you''re able to perform a variety of skills including killing enemies within a certain radius, chaining kills together based on your current combo, teleporting to your copy''s position and more.' FROM games WHERE igdb_id = 35122 ON CONFLICT (game_id, language_code) DO NOTHING;
