INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Musynx', 'Originally developed and published as a mobile app, MUSYNX has received overwhelmingly positive reviews and fan feedback from all over the world. PM Studios is now stepping in to help for this Nintendo Switch version to give it an all-new look from the inside out. The game will feature over 50 musical selections at release! Those who played MUSYNX on mobile are sure to have a familiar, yet totally fresh, experience when it releases on Nintendo Switch in 2018!' FROM games WHERE igdb_id = 75992 ON CONFLICT (game_id, language_code) DO NOTHING;
