INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Cars: Hit the Road', 'The cult racing series created in 1988 by Palace Software is back with a brand new version faster than ever before! Rediscover the sheer thrill of arcade gaming with this amazing racing game, taking bends at max speed or massive jumps that can go hundreds of meters high. You''ll be right in the middle of all the action, racing some of the best rides out there. Criss-cross different states of the USA at over 180 mph! Just make sure the cops don''t catch you.' FROM games WHERE igdb_id = 62976 ON CONFLICT (game_id, language_code) DO NOTHING;
