INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pillars of Eternity', 'Prepare to be enchanted by a world where the choices you make and the paths you choose shape your destiny. Recapture the deep sense of exploration, the joy of a pulsating adventure, and the thrill of leading your own band of companions across a new fantasy realm and into the depths of monster-infested dungeons in search of lost treasures and ancient mysteries.
