INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DmC: Devil May Cry - Definitive Edition', 'DmC: Devil May Cry - Definitive Edition includes all the stylish action gameplay from the original release, all previously released downloadable content, including the Vergil''s Downfall campaign plus brand new modes and additional content, making this the ultimate offering for Devil May Cry fans. Maximizing the potential of next-gen hardware, the game''s high quality production values will run at a stunning 1080p and smooth 60 fps across PlayStation 4 and Xbox One.' FROM games WHERE igdb_id = 20869 ON CONFLICT (game_id, language_code) DO NOTHING;
