INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend of Kay Anniversary', '10 years after its initial release, Legend of Kay - Anniversary is a thoroughly remastered version of the original game: high-resolution textures; new, more detailed character models; modern rendering techniques and crystal-clear surround sound give this great classic a new shine. Full of fond allusions to old martial arts films and pop culture quotes, Legend of Kay - Anniversary is both an incredibly funny game and a challenging action-adventure for young and old alike.' FROM games WHERE igdb_id = 19962 ON CONFLICT (game_id, language_code) DO NOTHING;
