INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tango Fiesta', 'Tango Fiesta is a top-down co-operative two stick shooter for 1 to 4 players. It is set in a world where the events from every single 80''s action film ever made actually happened to one unlucky ex-special-forces hero called John Strong, you and up to three friends get to blast, shoot, knife, and rescue your way through endless procedurally generated levels in the ultimate story of a one man army prevailing against every evil the world has ever known!' FROM games WHERE igdb_id = 9459 ON CONFLICT (game_id, language_code) DO NOTHING;
