INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pneuma: Breath of Life', 'Pneuma: Breath of Life is an enthralling first person puzzler putting gamers'' minds to the test in a visually stunning world using Unreal Engine 4 and Physically Based Rendering. Pneuma provides players with an unrivalled sense of adventure and a relentless determination to solve each puzzle and progress through a story of self-discovery, exploring the fundamental nature of being.
