INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario vs. Donkey Kong: Tipping Stars', 'In this puzzle/platformer hybrid, players guide Mario Minis to the exit door using touch control. As with previous games in the series, players can create their own levels and share them with other players online. In this game, players can “tip” the creators of the user-generated puzzles with stars, which can be used to buy new parts in the robust level creator.' FROM games WHERE igdb_id = 8594 ON CONFLICT (game_id, language_code) DO NOTHING;
