INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Majora''s Mask 3D', 'The Legend of Zelda: Majora''s Mask 3D is a remake of the original Nintendo 64 game with more up-to-date graphics, streamlined UI and different additional game modes. Most textures are significantly more detailed, and many models are more faithful to the game''s concept and promotional art. In addition, the frame rate has been increased to 30 FPS compared to the original''s 20 FPS.' FROM games WHERE igdb_id = 8593 ON CONFLICT (game_id, language_code) DO NOTHING;
