INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vietnam ''65', 'It is 1965 and the US ground war in Vietnam is in full swing. As a US Army commander, wage a counter-insurgency (COIN) war to secure the Ia Drang valley, on the border with Cambodia. Vietnam ''65 is a tun-based operational game that captures the true essence of the Vietnam War, where airmobile operations are paramount, fire support bases play a critical role and air strikes can save the day.' FROM games WHERE igdb_id = 36116 ON CONFLICT (game_id, language_code) DO NOTHING;
