INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warhammer 40,000: Regicide', 'Regicide, the strategy game based on chess set in the classic Warhammer 40,000 Universe from Games Workshop is an adaptation of ''Regicide'', a board game described from the Warhammer 40,000 universe with similarities to the M2-era chess; played by mankind for over thirty-eight thousand years. Regicide blends board-game strategy mechanics with dynamic tactical abilities.' FROM games WHERE igdb_id = 11450 ON CONFLICT (game_id, language_code) DO NOTHING;
