INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Isle', 'The Isle is intended to be a gritty, open-world survival horror game. Explore vast landscapes of dense forest and open plains, traverse treacherous mountains and wade through dark swamps where horrors lurk. Hidden within are ruins that hold insight as to what came before. Through it all, keep in mind there is only one goal: survive.' FROM games WHERE igdb_id = 25838 ON CONFLICT (game_id, language_code) DO NOTHING;
