INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kitten Squad', 'Sadistic robots have enslaved orcas at SeaLand Marine Park. The evil Sheep Puncher robot has kidnapped sheep for the twisted wool industry. Only the Kitten Squad is up to the task of saving these gentle animals. Players must guide the Kitten Squad, armed with weaponry ranging from carrot rocket launchers to yarn ball guns, on missions to defeat the evil robots and free the animals in this action game brought to you by PETA.' FROM games WHERE igdb_id = 30825 ON CONFLICT (game_id, language_code) DO NOTHING;
