INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angel Beats! 1st Beat', 'Angel Beats! 1st Beat is a Japanese visual novel based on the 2010 anime television series Angel Beats!, developed by Key and the first in a planned series of six volumes. It takes place in the afterlife and focuses on Otonashi, a boy who lost his memories of his life after dying. He is enrolled in the afterlife school and meets a girl named Yuri who invites him to join the Afterlife Battlefront, an organization she leads that fights against God. The Battlefront fights against the student council president Angel, a girl with supernatural powers.' FROM games WHERE igdb_id = 11414 ON CONFLICT (game_id, language_code) DO NOTHING;
