INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evoland 2', 'Evoland 2 is the spiritual successor to the original Evoland with its graphics style changing as you travel through time and its gameplay evolving as you move along the storyline. It is also a much bigger game and a classic RPG at heart, with a complex scenario based on time travel, dozens of characters with their own backgrounds and ambitions and vastly different gameplay styles that are linked to the story and the player’s actions.' FROM games WHERE igdb_id = 11798 ON CONFLICT (game_id, language_code) DO NOTHING;
