INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Everybody''s Gone to the Rapture', 'Deep within the Shropshire countryside, the village of Yaughton stands empty. Toys lie forgotten in the playground, the wind blows quarantine leaflets around the silent churchyard. Down on Appleton’s farm, crops rustle untended. The birds lie where they have fallen.
