INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakuoki: Kyoto Winds', '"This remastered telling of the beloved, visual novel Hakuoki series that was first developed and released in 2008 focuses on the story set in Kyoto. The young Chizuru, determined to find her father, will romance the famous samurai of Shinsengumi through a series of engaging stories and dramatic events. Now, experience new characters, love interests, and episodes in the world of Hakuoki: Kyoto Winds this Spring 2017!"' FROM games WHERE igdb_id = 25747 ON CONFLICT (game_id, language_code) DO NOTHING;
