INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Roller-Derby Disco Dodgeball', 'Disco Dodgeball is a physics-based first-person sports shooter set in a dance club. Dodge, deflect and catch enemy fire as you perform ridiculous aerial stunt shots. Play online or offline in a wide variety of game modes including Hoops, Capture The Flag, Grand Prix and of course, Classic Elimination.' FROM games WHERE igdb_id = 12877 ON CONFLICT (game_id, language_code) DO NOTHING;
