INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Missing Translation', 'Missing Translation is a simple puzzle game that is quite interesting in the way it presents itself. There are no tutorials, it allows for that special sort of exploration that many gamers love. There is no text dialogue or vocal dialogue, it is simply a game that can be enjoyed by anyone regardless of their language. Missing Translation is a beautiful experience both visually and emotionally, with a fantastic soundtrack, and a great art style.' FROM games WHERE igdb_id = 19173 ON CONFLICT (game_id, language_code) DO NOTHING;
