INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathtrap', 'Deathtrap is a Tower Defense game with strong action-RPG elements, a game of vicious tricks, killing machines, rotating blades and splattering blood. It shares the gothic fiction setting with NeocoreGames'' The Incredible Adventures of Van Helsing and features a lone protagonist who is sent to a border world in an alternate dimension ("Ink") to defend a series of ancient strongholds against a horde of monsters invading from the depths of that dimension and trying to break through to the physical world.' FROM games WHERE igdb_id = 7699 ON CONFLICT (game_id, language_code) DO NOTHING;
