INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overlord: Fellowship of Evil', 'Step into the warped fantasy world of Overlord: Fellowship of Evil, the dark and twisted Action RPG filled with the series’ signature black humour. Penned by award-winning original Overlord scriptwriter Rhianna Pratchett, Overlord: Fellowship of Evil delivers an epic new quest featuring four Netherghūls – undead servants of the dark arts, resurrected in the absence of a true Overlord, to bring evil back to a world overrun by the forces of good.' FROM games WHERE igdb_id = 9901 ON CONFLICT (game_id, language_code) DO NOTHING;
