INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChuSinGura46+1 V', 'The protagonist Fukami Suguha visits the historic graves of the forty-seven Akou rounin on New Year''s Day, but suddenly blacks out while observing the solar eclipse. He wakes up in the body of an Edo period samurai with the same name and face. Suguha is forced to adjust to life in the year 1701 as history unfolds, while getting to know the forty-seven rounin, whose personal details closely match history--except that many of them are women.' FROM games WHERE igdb_id = 335771 ON CONFLICT (game_id, language_code) DO NOTHING;
