INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('not-a-hero', 6045, '2015-05-14', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gjr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1da4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not a Hero', 'Professional assassin turned amateur campaign manager Steve is charged with cleaning up the city by an anthropomorphic rabbit and mayoral candidate from the future named BunnyLord. Now Steve and his expanding roster of dubious heroes must wield their unique skills to shoot, slide, dive and take cover behind a political platform built on ethics, accountability, and an inordinate amount of gunfire. Eliminate the criminal underworld of the city’s three major districts and persuade undecided voters to your cause, tackling the issues that matter by putting a gun in the mouth of those issues. Through the power of ISO-Slant technology and a wasted youth, London-based developer Roll7 (OlliOlli) delivers the greatest 2¼D cover-based indie shooter of all-time, ever.' FROM games WHERE igdb_id = 6045 ON CONFLICT (game_id, language_code) DO NOTHING;
